    k[i + rad] = Math.exp(-(i * i) / (2 * sigmaCells * sigmaCells));
  const z = k.reduce((a, b) => a + b, 0);
  const N = Math.max(W, H),
    nonzero = new Int32Array(N + 1),
    nonone = new Int32Array(N + 1);
  const nextNZ = new Int32Array(N),
    prevNZ = new Int32Array(N);
