    const d =
      cross(s2.a, s2.b, s1.a) /
      (cross(s2.a, s2.b, s1.a) - cross(s2.a, s2.b, s1.b));
    const x: Pt = [
      s1.a[0] + d * (s1.b[0] - s1.a[0]),
      s1.a[1] + d * (s1.b[1] - s1.a[1]),
    ];
